-- Copies Pillar default lookup rows into tenant lists.
-- @TenantId = a tenant: called by sign-up to seed that tenant.
-- @TenantId = NULL: publishes newly added defaults to every tenant.
-- Only inserts missing rows; tenant renames, reorders and deactivations are never overwritten.
-- RLS: the caller must set SESSION_CONTEXT TenantId to the tenant, or IsPlatformAdmin = 1 for NULL.
-- Generated by tools/GenerateLookups.py; edit the generator, not this file.
CREATE PROCEDURE lkp.usp_SyncTenantLookups
    @TenantId INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRAN;

    INSERT INTO lkp.ClientType (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.ClientType AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
           d.Id, d.SystemCode
    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultClientType AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.ClientType AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
      -- a tenant custom value may already hold the code; skip rather than fail
      AND NOT EXISTS (SELECT 1 FROM lkp.ClientType AS x WHERE x.TenantId = t.Id AND x.Code = d.Code);

    INSERT INTO lkp.ClientStatus (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.ClientStatus AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
           d.Id, d.SystemCode
    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultClientStatus AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.ClientStatus AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
      -- a tenant custom value may already hold the code; skip rather than fail
      AND NOT EXISTS (SELECT 1 FROM lkp.ClientStatus AS x WHERE x.TenantId = t.Id AND x.Code = d.Code);

    INSERT INTO lkp.PaymentTerm (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode, DueDays)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.PaymentTerm AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
           d.Id, d.SystemCode, d.DueDays
    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultPaymentTerm AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.PaymentTerm AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
      -- a tenant custom value may already hold the code; skip rather than fail
      AND NOT EXISTS (SELECT 1 FROM lkp.PaymentTerm AS x WHERE x.TenantId = t.Id AND x.Code = d.Code);

    INSERT INTO lkp.Industry (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.Industry AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
           d.Id, d.SystemCode
    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultIndustry AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.Industry AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
      -- a tenant custom value may already hold the code; skip rather than fail
      AND NOT EXISTS (SELECT 1 FROM lkp.Industry AS x WHERE x.TenantId = t.Id AND x.Code = d.Code);

    INSERT INTO lkp.AddressType (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.AddressType AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
           d.Id, d.SystemCode
    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultAddressType AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.AddressType AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
      -- a tenant custom value may already hold the code; skip rather than fail
      AND NOT EXISTS (SELECT 1 FROM lkp.AddressType AS x WHERE x.TenantId = t.Id AND x.Code = d.Code);

    INSERT INTO lkp.ContactRole (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
