    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultBillingType AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.BillingType AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
