    INSERT INTO lkp.ProjectType (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode, KeyPrefix, DefaultBillingTypeId)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.ProjectType AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
           d.Id, d.SystemCode, d.KeyPrefix, r_DefaultBillingTypeId.Id
    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultProjectType AS d
    LEFT JOIN lkp.BillingType AS r_DefaultBillingTypeId ON r_DefaultBillingTypeId.TenantId = t.Id AND r_DefaultBillingTypeId.DefaultId = d.DefaultBillingTypeId
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.ProjectType AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
      -- a tenant custom value may already hold the code; skip rather than fail
      AND NOT EXISTS (SELECT 1 FROM lkp.ProjectType AS x WHERE x.TenantId = t.Id AND x.Code = d.Code)
      AND NOT EXISTS (SELECT 1 FROM lkp.ProjectType AS x WHERE x.TenantId = t.Id AND x.KeyPrefix = d.KeyPrefix);

    INSERT INTO lkp.TaskStatus (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
           -- keep a default the tenant already chose
           CASE WHEN EXISTS (SELECT 1 FROM lkp.TaskStatus AS x WHERE x.TenantId = t.Id AND x.IsDefault = 1) THEN 0 ELSE d.IsDefault END,
