    FROM admin.Tenant AS t
    CROSS JOIN lkp.DefaultTaskStatus AS d
    WHERE (@TenantId IS NULL OR t.Id = @TenantId)
      AND NOT EXISTS (SELECT 1 FROM lkp.TaskStatus AS x WHERE x.TenantId = t.Id AND x.DefaultId = d.Id)
