    INSERT INTO lkp.PaymentMethod (TenantId, Code, Name, SortOrder, IsActive, IsCustom, IsLocked, IsDefault, DefaultId, SystemCode)
    SELECT t.Id, d.Code, d.Name, d.SortOrder, d.IsActive, 0, d.IsLocked,
